This is a heuristic solution; I have not compiled or run it. The approach has two phases: place servers into slots, then assign them to pools.

**Placement**
1. Sort servers by capacity/size ratio, descending.
2. Find the free segments in each row. Place servers greedily: take the best remaining server and put it in the row with the least capacity so far, in a segment that fits it.
3. To avoid wasting space, I place each server in the row with the lowest total capacity that has any segment where it fits. The first-fit position within that row is used.
4. If a server fits nowhere, it is skipped. A cheap search over rows is fine: M is up to 10^6 and R up to 1000, so I scan rows for each server. That is 10^9 in the worst case, which is too slow. Instead I keep a priority queue of rows by capacity. If the top row cannot fit the server, I pop it temporarily and try the next. Per-row free-space tracking is a vector of segments, searched first-fit with a pointer. A server of size z needs a segment with length ≥ z, so I scan the row's segment list, which is short-ish.

**Pool assignment**
1. Process the placed servers in descending capacity order.
2. Keep a table `cap[pool][row]` and a per-pool total.
3. For each server, pick the pool with the lowest guaranteed capacity, where the guarantee is total minus the max over rows of the row's capacity. Put the server in that pool.
4. P is up to 1000 and the server count is up to 10^6, so scanning all pools is 10^9. To be cheaper, I use a round-robin variant: sort servers descending and assign each to the pool with the smallest guaranteed capacity via a min-heap keyed by guaranteed capacity. The key changes only for the chosen pool, so I pop it, update its key, and push it back. Updating the guarantee costs O(R) for a max over rows, but I maintain the row max incrementally, because capacities only increase. The guarantee is then total − maxrow.

This gives the heap O(log P) per server, and the row-max update is O(1).

Since a pool's row distribution matters, the heap choice ignores which row the server is in. That is acceptable for a heuristic: the pool with the lowest guarantee gets the next server, and the row spread comes from the descending order and the least-loaded-row placement.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main(){
    int R,S,U,P,M;
    scanf("%d %d %d %d %d",&R,&S,&U,&P,&M);
    vector<vector<char>> bad(R,vector<char>(S,0));
    for(int i=0;i<U;i++){int r,s;scanf("%d %d",&r,&s);bad[r][s]=1;}
    vector<int> z(M),c(M);
    for(int i=0;i<M;i++)scanf("%d %d",&z[i],&c[i]);
    // segments per row
    vector<vector<pair<int,int>>> seg(R); // start,len
    for(int r=0;r<R;r++){
        int s=0;
        while(s<S){
            if(bad[r][s]){s++;continue;}
            int e=s;
            while(e<S&&!bad[r][e])e++;
            seg[r].push_back({s,e-s});
            s=e;
        }
    }
    vector<int> ord(M);
    iota(ord.begin(),ord.end(),0);
    stable_sort(ord.begin(),ord.end(),[&](int a,int b){
        return (long long)c[a]*z[b]>(long long)c[b]*z[a];
    });
    vector<long long> rowcap(R,0);
    vector<int> ar(M,-1),as(M,-1),ap(M,-1);
    typedef pair<long long,int> pli;
    priority_queue<pli,vector<pli>,greater<pli>> pq;
    for(int r=0;r<R;r++)pq.push({0,r});
    for(int idx=0;idx<M;idx++){
        int k=ord[idx];
        vector<pli> tmp;
        bool placed=false;
        while(!pq.empty()){
            pli t=pq.top();pq.pop();
            int r=t.second;
            bool ok=false;
            for(auto&sg:seg[r]){
                if(sg.second>=z[k]){
                    ar[k]=r;as[k]=sg.first;
                    sg.first+=z[k];sg.second-=z[k];
                    ok=true;break;
                }
            }
            if(ok){
                rowcap[r]+=c[k];
                pq.push({rowcap[r],r});
                placed=true;break;
            }
            // row can't fit this size; drop it only for this server
            tmp.push_back(t);
        }
        for(auto&t:tmp)pq.push(t);
    }
    // pool assignment
    vector<int> pl;
    for(int k=0;k<M;k++)if(ar[k]>=0)pl.push_back(k);
    stable_sort(pl.begin(),pl.end(),[&](int a,int b){return c[a]>c[b];});
    vector<long long> tot(P,0),mx(P,0);
    vector<vector<int>> pr(P,vector<int>(R,0));
    priority_queue<pli,vector<pli>,greater<pli>> hp;
    for(int p=0;p<P;p++)hp.push({0,p});
    for(int k:pl){
        pli t=hp.top();hp.pop();
        int p=t.second;
        ap[k]=p;
        tot[p]+=c[k];
        pr[p][ar[k]]+=c[k];
        mx[p]=max(mx[p],(long long)pr[p][ar[k]]);
        hp.push({tot[p]-mx[p],p});
    }
    for(int k=0;k<M;k++){
        if(ar[k]<0)puts("x");
        else printf("%d %d %d\n",ar[k],as[k],ap[k]);
    }
}
```
